const net = require('net');
const server = net.createServer();
server.once('error', (err) => {
  if (err.code === 'EADDRINUSE') {
    console.log('Port 3000 is in use locally');
  } else {
    console.log('Error:', err.message);
  }
  process.exit(0);
});
server.once('listening', () => {
  console.log('Port 3000 is FREE locally');
  server.close();
  process.exit(0);
});
server.listen(3000, '127.0.0.1');

const net = require('net');
const LOCAL_PORT = 4000;
const REMOTE_HOST = 'amyclaw-browser';
const REMOTE_PORT = 3000;

const server = net.createServer((localSocket) => {
  const remoteSocket = net.connect(REMOTE_PORT, REMOTE_HOST, () => {
    localSocket.pipe(remoteSocket);
    remoteSocket.pipe(localSocket);
  });
  remoteSocket.on('error', (err) => {
    console.error('Remote socket error:', err);
    localSocket.end();
  });
  localSocket.on('error', (err) => {
    console.error('Local socket error:', err);
    remoteSocket.end();
  });
});

server.listen(LOCAL_PORT, '127.0.0.1', () => {
  console.log(`Proxy listening on 127.0.0.1:${LOCAL_PORT} -> ${REMOTE_HOST}:${REMOTE_PORT}`);
});

