arguments.content:
#!/bin/bash
# High resolution screenshot wrapper for Browserless
URL=$1
OUTPUT=${2:-/tmp/screenshot.png}

curl -s -X POST -H "Content-Type: application/json" \
  -d "{
    \"url\": \"$URL\",
    \"viewport\": {\"width\": 1920, \"height\": 1080, \"deviceScaleFactor\": 2},
    \"options\": {\"fullPage\": false}
  }" \
  "http://amyclaw-browser:9222/screenshot?timeout=60000" \
  --output "$OUTPUT"

arguments.command:
cat << 'EOF' > /tmp/google_cdp.js
const { chromium } = require('/home/node/.openclaw/extensions/playwright/node_modules/playwright-core');

async function run() {
  const browser = await chromium.connectOverCDP('ws://amyclaw-browser:9222');
  const context = await browser.newContext({
    viewport: { width: 1920, height: 1080 },
    deviceScaleFactor: 2
  });
  const page = await context.newPage();

  console.log('Navigating to Google...');
  await page.goto('https://www.google.com', { waitUntil: 'networkidle' });

  const screenshotPath = '/tmp/google_cdp_highres.png';
  await page.screenshot({ path: screenshotPath });
  console.log('Screenshot saved to ' + screenshotPath);

  await browser.close();
}

run().catch(err => {
  console.error(err);
  process.exit(1);
});
