cat << 'EOF' > /tmp/google_cdp.js
const { chromium } = require('/home/node/.openclaw/skills/playwright-heavy-scraper/node_modules/playwright-core');

async function run() {
  const browser = await chromium.connectOverCDP('ws://amyclaw-browser:9222');
  // Playwright connectOverCDP usually shares contexts, but let's try to be clean
  const context = browser.contexts()[0] || await browser.newContext();
  const page = await context.newPage();

  // Set viewport for high res
  await page.setViewportSize({ width: 1920, height: 1080 });

  console.log('Navigating to Google...');
  await page.goto('https://www.google.com', { waitUntil: 'networkidle' });

  const screenshotPath = '/tmp/google_cdp_final.png';
  await page.screenshot({ path: screenshotPath });
  console.log('Screenshot saved to ' + screenshotPath);

  await page.close();
  // We don't close the browser to keep the CDP connection alive for future sessions if needed, 
  // but for browserless it's better to disconnect
}

run().catch(err => {
  console.error(err);
  process.exit(1);
});
